-- For God so loved the world, that He gave His only begotten Son,
-- that all who believe in Him should not perish but have everlasting life.
-- — John 3:16

-- EPHESIANS - SPA Combined
-- Generated: 2026-01-21T05:44:12.258Z

-- c006-v001: Los hijos obedeced a–los padres vuestros en Señor esto porque es justo
-- c006-v002: Honra al padre tuyo y a–la madre la–cual es mandamiento primero en promesa
-- c006-v003: para–que bien te vaya y seas de–larga–vida sobre la tierra
-- c006-v004: Y los padres no provoqueis–a–ira a–los hijos vuestros sino criadlos a–ellos en disciplina y instrucción del–Señor
-- c006-v005: Los siervos obedeced a–los según carne señores con temor y temblor en sencillez del corazón vuestro como al Christō
-- c006-v006: no con servicio–del–ojo como agradadores–de–hombres sino como siervos de–Christós haciendo la voluntad del Theós de alma
-- c006-v007: con buena–voluntad sirviendo como al Señor y no a–hombres
-- c006-v008: sabiendo que cada–uno si algo hiciere bueno esto recibirá del Señor sea siervo sea libre
-- c006-v009: Y los señores las mismas–cosas haced hacia ellos dejando la amenaza sabiendo que tanto de–ellos como vuestro el Señor está en cielos y acepción–de–personas no hay ante él
-- c006-v010: De–lo demás fortaleceos en Señor y en la potencia de–la fuerza de–él
-- c006-v011: Vestíos la armadura–completa del Theós para el poder vosotros estar–firmes contra las estratagemas del diablo
-- c006-v012: porque no es para–nosotros la lucha contra sangre y carne sino contra los principados contra las potestades contra los gobernadores–del–mundo de–la oscuridad esta contra los espirituales de–la maldad en los celestiales
-- c006-v013: Por esto tomad la armadura–completa del Theós para–que podáis resistir en el día el malo y todas–cosas habiendo–cumplido estar–firmes
-- c006-v014: Estad–firmes pues habiendo–ceñido los lomos vuestros con verdad y habiendo–vestido la coraza de–la justicia
-- c006-v015: y habiendo–calzado los pies en preparación del evangelio de–la paz
-- c006-v016: en todo habiendo–tomado el escudo de–la fe en el–cual podréis todos los dardos del maligno los encendidos apagar
-- c006-v017: Y el yelmo de–la salvación recibid y la espada del Espíritu la–cual es palabra de–Theós
-- c006-v018: por toda oración y súplica orando en todo tiempo en Espíritu y para esto velando en toda perseverancia y súplica por todos los santos
-- c006-v019: y por mí para–que me sea–dada palabra en abertura de–la boca mía con denuedo dar–a–conocer el misterio del evangelio
-- c006-v020: por el–cual soy–embajador en cadena para–que en él hable–con–denuedo como es–necesario me hablar
-- c006-v021: Para–que pero sepáis también vosotros las según mí qué hago todas–cosas dará–a–conocer a–vosotros Tychikós el amado hermano y fiel ministro en Señor
-- c006-v022: a–quien envié a vosotros para esto mismo para–que conozcáis las acerca–de nosotros y consuele los corazones vuestros
-- c006-v023: Paz a–los hermanos y amor con fe de Theós Padre y Señor Iēsoû Christoû
-- c006-v024: La gracia con todos los amando al Señor nuestro Iēsoûn Christón en incorrupción

